//! One disposable mounted read with actual native owners. Generated bytes and
//! offline capture injection only: no socket, provider or credential lease.
use super::*;
use crate::{
    access as a,
    app::{ReadAuthority, ServerRuntime, Store},
    config::providers::{
        network::NetworkSettings, network_host::NetworkBinding, registry::ProviderRegistry,
    },
    media::{self as m, AssetVault, native::NativeMediaRuntime},
    storage as s,
};
use axum::{
    body::{Body, to_bytes},
    extract::ConnectInfo,
    http::Request,
};
use n::{DurableNetworkSidecar, InventoryTransport};
use sha2::{Digest, Sha256};
use std::{
    fs,
    os::unix::fs::PermissionsExt,
    path::Path,
    sync::atomic::{AtomicBool, AtomicUsize, Ordering},
};
use tower::ServiceExt;
type Result<T> = std::result::Result<T, crate::lifecycle::Failure>;
const ORIGIN: &str = "https://127.0.0.1:48743";
const AT: &str = "2026-01-02T12:00:00Z";
fn id(n: u32) -> String {
    format!("00000000-0000-4000-8000-{n:012}")
}
fn hash(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
fn budget() -> m::WorkBudget {
    m::WorkBudget::new(std::time::Duration::from_secs(10), Default::default()).unwrap()
}
fn row(kind: &str, n: u32, payload: Value) -> Value {
    json!({"schemaVersion":1,"recordType":kind,"recordId":id(n),"workspaceId":id(1),"homeId":id(2),"revision":1,
        "lifecycle":"active","createdAt":AT,"updatedAt":AT,"lastAuditId":id(n+10000),"payload":payload})
}
fn evidence(n: u32, assets: &[u32]) -> Value {
    row(
        "evidence",
        n,
        json!({"statement":"Generated native route fixture", "provenance":{
        "source":null,"sourceRevision":null,"sourceConfidence":null,"evidenceBasis":"owner-report","factAt":null,
        "retrievedAt":AT,"vantage":null,"uncertainty":{"status":"unknown","explanation":null}},
        "supersedesEvidenceIds":[],"references":assets.iter().map(|n|json!({"kind":"atlas-asset","assetId":id(*n)})).collect::<Vec<_>>()}),
    )
}
fn asset(
    vault: &AssetVault,
    n: u32,
    purpose: &str,
    content: &str,
    evidence: u32,
    bytes: &[u8],
) -> Result<Value> {
    let sha = hash(bytes);
    let scope = m::types::Scope {
        workspace_id: id(1),
        home_id: id(2),
    };
    let record = row(
        "asset",
        n,
        json!({"owner":"atlas","purpose":purpose,"storageKey":scope.storage_key(&sha)?,"sha256":sha,
        "byteSize":bytes.len(),"contentType":content,"sourceLicense":{"status":"unknown","reference":null},
        "availability":"available","previewPolicy":"download-only","evidenceIds":[id(evidence)]}),
    );
    // Explicit synthetic bootstrap custody, not an upload or human approval.
    vault.restore_retained(&serde_json::from_value(record.clone())?, bytes, &budget())?;
    Ok(record)
}
struct Capture {
    config: n::NetworkHttpConfig,
    bytes: Vec<u8>,
    calls: AtomicUsize,
}
impl InventoryTransport for Capture {
    fn get_inventory(
        &self,
        _: n::InventoryGet,
        _: n::Limits,
    ) -> std::pin::Pin<
        Box<dyn std::future::Future<Output = n::Result<n::InventoryResponse>> + Send + '_>,
    > {
        panic!("Only the generated custodied setup capture is allowed")
    }
    fn get_inventory_with_custody(
        &self,
        _: n::InventoryGet,
        _: n::Limits,
    ) -> std::pin::Pin<
        Box<dyn std::future::Future<Output = n::Result<n::CustodiedInventoryResponse>> + Send + '_>,
    > {
        self.calls.fetch_add(1, Ordering::SeqCst);
        Box::pin(async {
            Ok(n::CustodiedInventoryResponse::synthetic(
                &self.config,
                n::InventoryResponse {
                    status: 200,
                    source: Some(self.config.source().scope.clone()),
                    body: self.bytes.clone(),
                    source_snapshot_at: Some(AT.into()),
                    redirected: false,
                    location: None,
                    url: None,
                },
            ))
        })
    }
}
async fn get(host: &Host, cookie: &str, query: bool) -> Result<(StatusCode, Value)> {
    let path = format!(
        "/api/atlas/scene/v1/workspaces/{}/homes/{}/buildings/{}/current{}",
        id(1),
        id(2),
        id(1000),
        if query { "?networkLiveFacts=2" } else { "" }
    );
    let mut request = Request::builder()
        .uri(path)
        .header("host", "127.0.0.1:48743")
        .header("origin", ORIGIN)
        .header("sec-fetch-site", "same-origin")
        .header("cookie", cookie)
        .body(Body::empty())?;
    request.extensions_mut().insert(ConnectInfo(
        "127.0.0.1:50123".parse::<std::net::SocketAddr>()?,
    ));
    let response = router(host.clone()).oneshot(request).await?;
    let status = response.status();
    let body = serde_json::from_slice(&to_bytes(response.into_body(), 1024 * 1024).await?)?;
    Ok((status, body))
}
fn links(
    root: &Path,
    file: &str,
    sha: &str,
    collection: &str,
) -> Result<crate::config::atlas_device_links::ServerAtlasDeviceLinksSelection> {
    let folder = root.join(file.trim_end_matches(".json"));
    fs::create_dir(&folder)?;
    fs::set_permissions(&folder, fs::Permissions::from_mode(0o700))?;
    let path = folder.join("links.json");
    let bytes = serde_json::to_vec(
        &json!({"profile":"houseatlas.atlas-device-links.v1","links":[{
        "sceneOriginalSha256":sha,"documentaryDeviceId":"documentary-a","source":{"workspaceId":id(1),"homeId":id(2),
        "sourceInstanceId":id(12),"collectionId":collection,"sourceKind":"network-device","externalId":"device-a"},
        "reviewStatus":"accepted","reviewer":"Synthetic owner","reviewedAt":AT,"evidenceReference":"synthetic:route-review"}]}),
    )?;
    fs::write(&path, &bytes)?;
    fs::set_permissions(&path, fs::Permissions::from_mode(0o600))?;
    Ok(
        crate::config::atlas_device_links::ServerAtlasDeviceLinksSelection::read_pinned(
            &path,
            &hash(&bytes),
        )?,
    )
}
pub(super) async fn run() -> Result<()> {
    let temporary = tempfile::Builder::new()
        .permissions(fs::Permissions::from_mode(0o700))
        .tempdir()?;
    let root = fs::canonicalize(temporary.path())?;
    let vault = Arc::new(AssetVault::open(&root.join("media"))?);
    let (ifc, glb) = m::ifc_glb::synthetic_floor_bytes();
    let mut records = vec![
        row(
            "identity",
            1000,
            json!({"kind":"location","evidenceIds":[id(1004),id(1011)]}),
        ),
        row(
            "location-semantics",
            1001,
            json!({"atlasId":id(1000),"semanticKind":"building","reviewStatus":"accepted","evidenceIds":[id(1004)]}),
        ),
        evidence(1004, &[1005, 1006]),
        evidence(1011, &[1010]),
        evidence(1013, &[1012]),
        row(
            "geometry",
            1003,
            json!({"producer":"ifc","producerVersion":null,"importedAt":AT,"exportFormat":"ifc","originalAssetId":id(1005),"coordinateUnits":"unknown",
            "scale":null,"transform":null,"mappings":[],"geometryVersion":1,"previousGeometryId":null,"evidenceIds":[id(1004)]}),
        ),
        asset(
            &vault,
            1005,
            "geometry-original",
            "application/x-step",
            1004,
            &ifc,
        )?,
        asset(
            &vault,
            1006,
            "derived-preview",
            "model/gltf-binary",
            1004,
            &glb,
        )?,
    ];
    let partial = s::Snapshot {
        records: serde_json::from_value(json!(records))?,
        ..Default::default()
    };
    let floor = m::geometry_bundle::floors(
        &partial,
        &s::Scope {
            workspace_id: id(1),
            home_id: id(2),
        },
        &id(1000),
        &vault,
        &budget(),
    )?
    .remove(0)
    .descriptor;
    let anchors = json!([{"id":"synthetic-anchor","sourceFloorKey":"source-floor","sourceOriginalSha256":floor.original_sha256,"targets":[],"unresolvedLabels":[]}]);
    let historical = b"Generated historical documentary source.\n";
    let receipt = crate::contracts::semantics::canonical_json(
        &json!({"profile":"houseatlas.native-scene-room-review.v1","receiptId":"synthetic-room-review","sourceReceiptSha256":hash(historical),"anchors":anchors}),
    )?;
    let primary = serde_json::to_vec(
        &json!({"schema":"houseatlas.native-scene-source.v1","receiptCanonicalJson":receipt,
        "rooms":{"status":"available","reason":null,"receiptId":"synthetic-room-review","receiptSha256":hash(receipt.as_bytes()),"entries":[],"regions":[]},
        "network":{"status":"available","reason":null,"source":{"label":"Generated network","revision":null,"recordedAt":AT,"retrievedAt":AT,"status":"recorded","acceptedAt":null,"coverage":"partial","notes":""},
            "devices":[{"id":"documentary-a","label":"Generated device","kind":"router","mobility":"unknown","confidence":"recorded","notes":"","place":null}],"endpoints":[],"links":[]},
        "electricity":{"status":"unavailable","reason":"not-retained","documentarySource":null,"roomRegistry":null,"buildingPackageKey":null,"retrievedAt":null}}),
    )?;
    records.push(asset(
        &vault,
        1010,
        "evidence-original",
        "text/plain",
        1011,
        &primary,
    )?);
    records.push(asset(
        &vault,
        1012,
        "evidence-original",
        "text/plain",
        1013,
        historical,
    )?);
    records.push(row("scene-association",1002,json!({"profile":"houseatlas.native-scene-association.v1","buildingId":id(1000),"associationVersion":1,"previousAssociationId":null,
        "reviewStatus":"accepted","reviewStatement":"Synthetic route review","sourceDocuments":[
            {"role":"primary-scene","evidenceId":id(1011),"evidenceRevision":1,"originalAssetId":id(1010),"originalAssetRevision":1,"originalSha256":hash(&primary),"contentType":"text/plain"},
            {"role":"documentary-sheet","evidenceId":id(1013),"evidenceRevision":1,"originalAssetId":id(1012),"originalAssetRevision":1,"originalSha256":hash(historical),"contentType":"text/plain"}],
        "acceptedReceipt":{"receiptId":"synthetic-room-review","canonicalJson":receipt,"canonicalSha256":hash(receipt.as_bytes()),"anchors":anchors},
        "sourceFloors":[{"sourceFloorKey":"source-floor","sourceOriginalSha256":floor.original_sha256,"nativeFloorKey":floor.key,"nativeGeometryId":id(1003),"nativeGeometryRevision":1,"nativeOriginalAssetId":id(1005),"nativeOriginalSha256":floor.original_sha256}],"roomMappings":[]})));
    let registration: s::SourceRegistration = serde_json::from_value(
        json!({"workspaceId":id(1),"homeId":id(2),"sourceInstanceId":id(12),"collectionId":"inventory","owner":"network","partitionMode":"exclusive-home","allowedExternalIds":[]}),
    )?;
    let registry = ProviderRegistry::from_trusted_configuration(vec![registration.clone()])?;
    let settings = NetworkSettings::new(
        registry.sources()[0].clone(),
        ORIGIN,
        serde_json::from_str(include_str!(
            "../../../../adapters/network/fixtures/link-review.json"
        ))?,
        n::Limits::default(),
        2000,
        2000,
        60000,
        &root,
    )?;
    let mut wire: Value = serde_json::from_str(include_str!(
        "../../../../adapters/network/fixtures/inventory.wire.json"
    ))?;
    wire["inventory"]["interfaces"][0]["addresses"] = json!(["", "192.0.2.1"]);
    let capture = Capture {
        config: settings.transport(),
        bytes: serde_json::to_vec(&wire)?,
        calls: AtomicUsize::new(0),
    };
    let now = s::Runtime::now(&ServerRuntime)?;
    let mut provider = settings.provider()?;
    let n::RefreshOutcome::Complete(proposal) = provider
        .prepare_refresh(
            &n::RetainedState::empty(settings.source().scope.clone()),
            0,
            &id(90),
            &capture,
            || now.clone(),
        )
        .await?
    else {
        return Err("Generated capture failed".into());
    };
    let state = proposal.state();
    let generation = state
        .generation
        .as_ref()
        .ok_or("Missing synthetic generation")?;
    let refs = n::host_runtime::generation_references(settings.source(), generation)?;
    let mut sidecar = settings.open_sidecar()?;
    let reservation = sidecar.reserve_original_capture(
        settings.source(),
        settings.review(),
        &id(90),
        n::Limits::default(),
    )?;
    let projected = sidecar.stage(
        settings.source(),
        &n::stage_row(settings.source(), &proposal)?,
    )?;
    sidecar.stage_original_capture(reservation, &proposal, &projected)?;
    sidecar.close()?;
    let snapshot: s::Snapshot = serde_json::from_value(
        json!({"contractVersion":s::CONTRACT_VERSION,"synthetic":true,"sources":[registration],"records":records,
        "homeboxEntities":[],"caches":[state.cache],"networkRelations":generation.network_relations}),
    )?;
    let access = Arc::new(Mutex::new(a::AccessBoundary::open(
        root.join("access.sqlite"),
        a::AccessConfig::new(vec![ORIGIN.into()])?,
    )?));
    let access_scope = a::Scope {
        workspace_id: a::CanonicalId::parse(&id(1))?,
        home_id: a::CanonicalId::parse(&id(2))?,
    };
    let cookie = {
        let mut access = access.lock().unwrap();
        let user = a::CanonicalId::parse(&id(4))?;
        let actor = a::CanonicalId::parse(&id(5))?;
        access.provision_user(
            &user,
            &actor,
            "synthetic-viewer",
            &a::hash_password("Generated-only-fixture-password")?,
            None,
        )?;
        access.set_membership(&user, &access_scope, a::Role::Viewer, true)?;
        let login=access.login(&a::RequestEvidence{method:a::Method::Post,url:&format!("{ORIGIN}/api/atlas/auth/login"),origin:Some(ORIGIN),sec_fetch_site:Some("same-origin"),referer:None,cookie:None,authorization:None,csrf:None},
            &serde_json::to_vec(&json!({"username":"synthetic-viewer","password":"Generated-only-fixture-password"}))?,"synthetic-test")?;
        login
            .set_cookie()
            .split(';')
            .next()
            .ok_or("Missing generated cookie")?
            .to_owned()
    };
    let database = root.join("atlas.sqlite");
    let mut store = Store::open(
        &database,
        contracts::NativeContracts,
        ReadAuthority(access.clone()),
        NativeMediaRuntime {
            vault: vault.clone(),
            server: ServerRuntime,
        },
        s::StoreOptions {
            allow_synthetic_bootstrap: true,
            ..Default::default()
        },
    )?;
    store.initialize_synthetic(&snapshot)?;
    let home = d::HomeSummary {
        scope: d::Scope {
            workspace_id: id(1),
            home_id: id(2),
        },
        label: "Synthetic home".into(),
    };
    let core = Core {
        access: access.clone(),
        store: Arc::new(Mutex::new(store)),
        vault,
        home: home.clone(),
        homes: vec![home],
        atlas_list_pages: Default::default(),
        media_policy_evidence: Mutex::default(),
    };
    let binding = NetworkBinding::from_trusted_configuration(
        &core,
        settings.for_existing_cached_storage(),
        refs,
    )?;
    let mut host = Host::new(core, ORIGIN.into(), Arc::new(BTreeMap::new()), vec![])?
        .with_network_bindings(vec![binding])?
        .with_atlas_device_links(links(&root, "links.json", &hash(&primary), "inventory")?)?;
    // Genuine home Viewer authority exists, but no Network registration/grants.
    let (status, base) = get(&host, &cookie, false).await?;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(base["status"], "available");
    let (status, denied) = get(&host, &cookie, true).await?;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert!(denied.get("networkLiveFacts").is_none());
    let native_registration = serde_json::from_value(serde_json::to_value(&registration)?)?;
    access
        .lock()
        .unwrap()
        .put_source(&native_registration, Some(true))?;
    let (status, joined) = get(&host, &cookie, true).await?;
    assert_eq!(status, StatusCode::OK, "{joined}");
    assert_eq!(
        joined["networkLiveFacts"]["devices"][0]["liveFacts"]["addresses"],
        json!(["", "192.0.2.1"])
    );
    assert_eq!(joined["association"], base["association"]);
    let mismatch = host.clone().with_atlas_device_links(links(
        &root,
        "other-links.json",
        &hash(&primary),
        "other-partition",
    )?)?;
    let (status, body) = get(&mismatch, &cookie, true).await?;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert!(body.get("networkLiveFacts").is_none());
    let partition = native_registration.partition();
    access
        .lock()
        .unwrap()
        .set_source_enabled(&partition, false)?;
    let (status, body) = get(&host, &cookie, true).await?;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert!(body.get("networkLiveFacts").is_none());
    access
        .lock()
        .unwrap()
        .set_source_enabled(&partition, true)?;
    // Change only the native cache baseline after preparation. Home/source grants
    // stay valid, so removing the Network lease's final revalidation breaks this.
    let crossed = Arc::new(AtomicBool::new(false));
    let observed = crossed.clone();
    let database_copy = database.clone();
    host.network_overlay_before_release = Some(Arc::new(move || {
        let db = rusqlite::Connection::open(&database_copy).unwrap();
        db.execute("UPDATE cache_epochs SET epoch=epoch+1", [])
            .unwrap();
        observed.store(true, Ordering::SeqCst);
    }));
    let (status, body) = get(&host, &cookie, true).await?;
    assert!(crossed.load(Ordering::SeqCst));
    assert_ne!(status, StatusCode::OK);
    assert!(body.get("networkLiveFacts").is_none());
    host.network_overlay_before_release = None;
    // A fresh read can capture the new epoch, then a quarantined cache withholds
    // facts instead of turning an unavailable generation into device absence.
    let (status, _) = get(&host, &cookie, true).await?;
    assert_eq!(status, StatusCode::OK);
    let mut revoked = serde_json::to_value(&state.cache)?;
    revoked["status"] = json!("access-revoked");
    revoked["error"] = json!({"code":"auth","at":now,"message":"Network access is unavailable"});
    let db = rusqlite::Connection::open(&database)?;
    db.execute(
        "UPDATE caches SET body=?1",
        [serde_json::to_string(&revoked)?],
    )?;
    db.execute("UPDATE cache_epochs SET epoch=epoch+1", [])?;
    drop(db);
    let (status, withheld) = get(&host, &cookie, true).await?;
    assert_eq!(status, StatusCode::OK, "{withheld}");
    assert_eq!(withheld["networkLiveFacts"]["devices"], json!([]));
    assert_eq!(withheld["association"], base["association"]);
    assert_eq!(
        capture.calls.load(Ordering::SeqCst),
        1,
        "No route may collect or refresh"
    );
    Ok(())
}
